    'always_after': {
        ('CA', 'RO'), ('RI', 'CA'), ('PI', 'RI'), ('QC', 'PI'),
        ('PO', 'QC'), ('GSL', 'PO'), ('D', 'GSL'), ('IC', 'D'), ('RP', 'IC')
    },
    'never_together': set(),
    'activ_freq': {
        'RO': {1}, 'CA': {1}, 'RI': {1}, 'PI': {1}, 'QC': {1},
        'PO': {1}, 'GSL': {1}, 'D': {1}, 'IC': {1}, 'RP': {1}
    },
    'directly_follows': {
